import { motion } from 'framer-motion';

const Skills = () => {
  const stats = [
    { label: "LeetCode", value: "150+ Solved", detail: "Arrays, Strings, DP" }, // [cite: 39]
    { label: "HackerRank", value: "5-Star Gold", detail: "Advanced SQL" } // [cite: 40]
  ];

  return (
    <section id="skills" className="py-20 px-10 bg-white">
      <div className="container mx-auto">
        <div className="grid md:grid-cols-2 gap-16">
          {/* Achievements Side */}
          <div>
            <h3 className="text-3xl font-black mb-8 uppercase tracking-tighter">Achievements</h3>
            <div className="flex gap-6">
              {stats.map((stat, i) => (
                <motion.div 
                  key={i}
                  whileHover={{ scale: 1.05 }}
                  className="bg-black text-white p-6 rounded-2xl flex-1 shadow-xl"
                >
                  <p className="text-brand-blue font-bold text-sm uppercase">{stat.label}</p>
                  <h4 className="text-2xl font-black my-1">{stat.value}</h4>
                  <p className="text-gray-400 text-xs">{stat.detail}</p>
                </motion.div>
              ))}
            </div>
          </div>

          {/* Languages/Tools Side */}
          <div>
            <h3 className="text-3xl font-black mb-8 uppercase tracking-tighter">Stack</h3>
            <div className="flex flex-wrap gap-3">
              {["C++", "Python", "Java", "React.js", "FastAPI", "SQL", "Docker"].map((skill) => ( // [cite: 5, 7, 15]
                <span key={skill} className="px-5 py-2 border-2 border-gray-100 rounded-full font-bold hover:border-black transition-colors cursor-default">
                  {skill}
                </span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
